patch:
--- a/src/cpu.hpp
+++ b/src/cpu.hpp
@@ -92,7 +92,7 @@
     std::string location() const;

     struct TLBEntry {
-        uint32_t tag = 0, epoch = 0, base = 0, pteAddress = 0;
+        uint32_t tag = 0, epoch = 0, bias = 0, pteAddress = 0;
         uint8_t permissions = 0;
         bool dirty = false;
     };
--- a/src/cpu.cpp
+++ b/src/cpu.cpp
@@ -83,7 +83,7 @@
         if ((!(entry.permissions & 4) || (wr && !(entry.permissions & 2))) &&
             cpl() == 3 && !systemAccess)
             return physicalSlow(a, wr);
-        a = entry.base | (a & 4095);
+        a = entry.bias + a;
     }
     if (!a20) a &= ~(1u << 20);
     return a;
@@ -132,7 +132,7 @@
             std::memcpy(&mem[pdeAddress], &pde, 4);
             written(pteAddress, 4);
             std::memcpy(&mem[pteAddress], &pte, 4);
-            entry = {page,          tlbEpoch, pte & ~4095u, pteAddress, uint8_t(permissions),
+            entry = {page,          tlbEpoch, (pte & ~4095u) - (page << 12), pteAddress, uint8_t(permissions),
                      bool(pte & 64)};
         }
         if ((!(entry.permissions & 4) || (wr && !(entry.permissions & 2))) && user())
@@ -142,7 +142,7 @@
             mem[entry.pteAddress] |= 64;
             entry.dirty = true;
         }
-        a = entry.base | (a & 4095);
+        a = entry.bias + a;
     }
     if (!a20)
         a &= ~(1u << 20);
@@ -1079,7 +1079,7 @@
                         ready = tlbCR3 == cr[3] && entry.epoch == tlbEpoch &&
                                 entry.tag == page && entry.dirty &&
                                 (cpl() != 3 || systemAccess || (entry.permissions & 6) == 6);
-                        physicalStart = entry.base | (dst & 4095);
+                        physicalStart = entry.bias + dst;
                     }
                     uint32_t bytes = elements * bw;
                     ready = ready && elements > 1 && uint64_t(physicalStart) + bytes <= mem.size() &&
@@ -1126,7 +1126,7 @@
                                 (cpl() == 3 && !systemAccess &&
                                  (entry.permissions & permissions) != permissions))
                                 return false;
-                            physicalStart = entry.base | (linear & 4095);
+                            physicalStart = entry.bias + linear;
                         }
                         if (uint64_t(physicalStart) + bytes > mem.size() ||
                             (physicalStart < 0xb0000 && uint64_t(physicalStart) + bytes > 0xa0000))
--- a/src/jit.cpp
+++ b/src/jit.cpp
@@ -18,7 +18,7 @@
         const auto &entry = cpu.tlb[(page ^ (page >> 10)) & (cpu.tlb.size() - 1)];
         if (cpu.tlbCR3 == cpu.cr[3] && entry.epoch == cpu.tlbEpoch && entry.tag == page &&
             ((entry.permissions & 4) || cpu.cpl() != 3 || cpu.systemAccess)) {
-            uint32_t physical = entry.base | (linear & 4095);
+            uint32_t physical = entry.bias + linear;
             if (!cpu.a20) physical &= ~(1u << 20);
             return physical >> 12;
         }
--- a/src/jit_arm64.cpp
+++ b/src/jit_arm64.cpp
@@ -779,9 +779,8 @@
                         emit(0x3940458du);  // ldrb w13,[x12,#dirty]
                         guard(0x3400000du); // cbz w13,slow
                     }
-                    emit(0x12002d2eu); // and w14,w9,#4095
-                    load(13, 12, offsetof(CPU::TLBEntry, base));
-                    emit(0x2a0e01a9u); // orr w9,w13,w14
+                    load(13, 12, offsetof(CPU::TLBEntry, bias));
+                    emit(0x0b0d0129u); // add w9,w9,w13
                 }
                 if (!block.a20) {
                     imm(10, 1u << 20);
--- a/src/snapshot.cpp
+++ b/src/snapshot.cpp
@@ -172,8 +172,12 @@
         a(c.cr, c.dr, c.gdtBase, c.idtBase, c.ldtBase, c.gdtLimit, c.idtLimit, c.ldtLimit,
           c.ldtSelector, c.trSelector, c.trBase, c.trLimit, c.tr32, c.halted, c.a20, c.instructions,
           c.interruptBlockedThrough, c.systemAccess);
-        for (auto &e : c.tlb)
-            a(e.tag, e.epoch, e.base, e.pteAddress, e.permissions, e.dirty);
+        for (auto &e : c.tlb) {
+            uint32_t frame = e.bias + (e.tag << 12);
+            a(e.tag, e.epoch, frame, e.pteAddress, e.permissions, e.dirty);
+            if constexpr (A::loading)
+                e.bias = frame - (e.tag << 12);
+        }
         a(c.tlbEpoch, c.tlbCR3);
         auto &r = c.repeatResume;
         a(r.valid, r.selector, r.base, r.ip, r.initialFlags, r.lastFlags, r.ax, r.cx, r.si, r.di);
--- a/tests/test.cpp
+++ b/tests/test.cpp
@@ -86,13 +86,13 @@
             for (unsigned permissions = 0; permissions < 256; ++permissions)
             for (bool dirty : {false, true}) {
                 auto &entry = c.tlb[9];
-                entry = {9, c.tlbEpoch, base, 0x100, uint8_t(permissions), dirty};
-                check(entry.base == base && entry.permissions == permissions && entry.dirty == dirty,
+                entry = {9, c.tlbEpoch, uint32_t(base - 0x9000), 0x100, uint8_t(permissions), dirty};
+                check(entry.bias == uint32_t(base - 0x9000) && entry.permissions == permissions && entry.dirty == dirty,
                       "TLB frame and metadata retain every bit");
                 check(c.physical(0x9abc) == (base | 0xabc),
                       "TLB metadata cannot change a physical address");
                 entry.dirty = true;
-                check(entry.dirty && entry.base == base && entry.permissions == permissions,
+                check(entry.dirty && entry.bias == uint32_t(base - 0x9000) && entry.permissions == permissions,
                       "dirty update preserves frame and permissions");
             }
         }
@@ -117,7 +117,7 @@
             c.a20 = a20;
             auto page = linear >> 12;
             auto &entry = c.tlb[(page ^ (page >> 10)) & (c.tlb.size() - 1)];
-            entry = {page, c.tlbEpoch, 0x180000, pte, uint8_t(permissions), dirty};
+            entry = {page, c.tlbEpoch, uint32_t(0x180000 - (page << 12)), pte, uint8_t(permissions), dirty};
             if (cache == 1) entry.tag ^= 1;
             if (cache == 2) --entry.epoch;
             if (cache == 3) c.tlbCR3 ^= 0x1000;
--- a/tests/snapshot_test.cpp
+++ b/tests/snapshot_test.cpp
@@ -186,7 +186,7 @@
         m.cpu.interruptBlockedThrough = 12345679;
         m.cpu.s[FS] = {0x123400, 0xffff, 0x31, false, true};
         m.cpu.repeatResume = {true, 7, 0x1234, 0x20, 0x202, 0x246, 1, 2, 3, 4};
-        m.cpu.tlb[17] = {0x19, m.cpu.tlbEpoch, 0x5000, 0x1a00, 6, true};
+        m.cpu.tlb[17] = {0x19, m.cpu.tlbEpoch, uint32_t(0x5000 - 0x19000), 0x1a00, 6, true};
         m.cpu.write(0x5000, 0xaabbccdd, 4);
         m.pic[0].irr = 5;
         m.pic[1].isr = 0x40;
@@ -247,7 +247,7 @@
               "CPU RAM and cache identity restore");
         check(m.disk->isOverlay() && fs::file_size(m.disk->path) < 1024,
               "restore allocates only an empty compressed delta");
-        check(m.cpu.tlb[17].base == 0x5000 && m.cpu.tlb[17].pteAddress == 0x1a00 &&
+        check(m.cpu.tlb[17].bias == uint32_t(0x5000 - 0x19000) && m.cpu.tlb[17].pteAddress == 0x1a00 &&
                   m.cpu.tlb[17].permissions == 6 && m.cpu.tlb[17].dirty,
               "legacy snapshot fields restore frame/permission/dirty state");
         m.saveSnapshot((root / "roundtrip").string());
